/**
 * Access to the precomputed SPICE samples. [M-EPHEM]
 *
 * Each sample holds the apparent (LT+S) Sun and Earth position vectors
 * relative to the Moon's centre in the Mean-Earth body-fixed frame, km, at
 * uniform UTC steps (public/data/ephemeris_<year>.bin, generated by
 * scripts/build_data.py from DE440) [R-DE440] [R-NAIF-ABCORR].
 * Between samples the vectors are interpolated linearly; the measured error of
 * that interpolation is recorded in ephemeris.json (interpolation.max_error_vs_spice).
 */
import type { Vec3 } from './geometry';

export type Body = 'sun' | 'earth';

export interface EphemerisTable {
  /** UTC epoch of sample 0, milliseconds since 1970-01-01T00:00:00Z. */
  t0Ms: number;
  /** Sample spacing, milliseconds. */
  stepMs: number;
  /** Number of samples. */
  n: number;
  /** n x 6 values: sun xyz, earth xyz (km). */
  data: Float64Array;
}

const OFFSET: Record<Body, number> = { sun: 0, earth: 3 };

export function tableFromBuffer(buffer: ArrayBuffer, t0Ms: number, stepMs: number): EphemerisTable {
  if (buffer.byteLength % 48 !== 0) throw new Error('ephemeris file size is not a multiple of 6 float64');
  const data = new Float64Array(buffer);
  return { t0Ms, stepMs, n: data.length / 6, data };
}

/**
 * Join consecutive tables (each year file repeats the first sample of the next
 * year as its last sample). Tables must be contiguous and share the step.
 */
export function mergeTables(parts: EphemerisTable[]): EphemerisTable {
  if (parts.length === 0) throw new Error('no ephemeris tables');
  const sorted = [...parts].sort((a, b) => a.t0Ms - b.t0Ms);
  const stepMs = sorted[0].stepMs;
  let n = sorted[0].n;
  for (let i = 1; i < sorted.length; i++) {
    const prev = sorted[i - 1];
    if (sorted[i].stepMs !== stepMs) throw new Error('ephemeris tables have different steps');
    if (sorted[i].t0Ms !== prev.t0Ms + (prev.n - 1) * stepMs) throw new Error('ephemeris tables are not contiguous');
    n += sorted[i].n - 1;
  }
  const data = new Float64Array(n * 6);
  let at = 0;
  sorted.forEach((p, i) => {
    const src = i === 0 ? p.data : p.data.subarray(6);
    data.set(src, at);
    at += src.length;
  });
  return { t0Ms: sorted[0].t0Ms, stepMs, n, data };
}

export const tableEndMs = (t: EphemerisTable): number => t.t0Ms + (t.n - 1) * t.stepMs;

/**
 * Moon-centred body vector (km, ME frame) at an arbitrary UTC time by linear
 * interpolation between the two bracketing samples. Throws outside coverage:
 * the table is never extrapolated.
 */
export function bodyVectorKm(table: EphemerisTable, tMs: number, body: Body): Vec3 {
  const f = (tMs - table.t0Ms) / table.stepMs;
  if (!(f >= 0 && f <= table.n - 1)) {
    throw new RangeError(`time ${new Date(tMs).toISOString()} is outside the ephemeris coverage`);
  }
  const i = Math.min(Math.floor(f), table.n - 2);
  const w = f - i;
  const a = i * 6 + OFFSET[body];
  const b = a + 6;
  const d = table.data;
  return [
    d[a] + (d[b] - d[a]) * w,
    d[a + 1] + (d[b + 1] - d[a + 1]) * w,
    d[a + 2] + (d[b + 2] - d[a + 2]) * w,
  ];
}
